const cached = await store.get(key);
if (cached) render(cached, { stale: true });     // 먼저 보여 주고
try {
  const fresh = await api.get(key);
  await store.set(key, fresh);
  render(fresh);                                 // 오면 갱신
} catch {
  showBanner('오프라인 — 마지막으로 받은 내용입니다');
}

async function postComment(text) {
  const temp = { id: `tmp-${Date.now()}`, text, pending: true };
  addToUI(temp);                       // 먼저 화면에
  await outbox.add({ type: 'comment', text, key: temp.id });   // 저장(IndexedDB)
  void flushOutbox();                  // 연결되면 보낸다
}
